parameters.jsCode:
// Accuracy, precision, recall, F1, and the confusion matrix.
//
// Four numbers rather than one, because accuracy alone lies in two specific
// ways that matter here.
//
// It hides class imbalance. The 46 labels are 16 accepted, 12 review,
// 11 rejected and 7 invalid -- counted off the loaded table, not guessed --
// so a rule that accepted everything and read nothing would score 0.35.
// Macro F1 gives that rule about 0.13, which is the honest description.
//
// And it treats every mistake as equal, which they are not. Accepting
// somebody who should have been rejected costs money; rejecting somebody who
// should have been accepted costs a creator who never applies again. Those
// are counted separately at the bottom and reported separately, because the
// right trade between them is a business decision and not a rounding one.

const CLASSES = ['accepted', 'review', 'rejected', 'invalid'];
const r4 = (n) => (n === null ? null : Number(n.toFixed(4)));

const scored = $input.all().map((i) => i.json);

const cases = scored.map((row) => ({
  external_id: row.external_id,
  expected: row.expected_decision,
  actual: row.decision,
  correct: row.expected_decision === row.decision,
  note: row.note ?? null,
}));

const total = cases.length;
if (total === 0) {
  // An empty golden set would otherwise score 0/0 and report a cheerful 1.0.
  throw new Error('golden set is empty: run n8n/sql/02-golden-set.sql');
}

const correct = cases.filter((c) => c.correct).length;
const accuracy = correct / total;

const per_class = {};
let f1_sum = 0;
let classes_present = 0;

for (const cls of CLASSES) {
  const tp = cases.filter((c) => c.actual === cls && c.expected === cls).length;
  const fp = cases.filter((c) => c.actual === cls && c.expected !== cls).length;
  const fn = cases.filter((c) => c.expected === cls && c.actual !== cls).length;
  const support = tp + fn;

  // null, not 0, when the denominator is empty. A class nothing was predicted
  // for has undefined precision, and writing it down as 0 drags the macro
  // average toward a number that describes an absence rather than a mistake.
  const precision = tp + fp > 0 ? tp / (tp + fp) : null;
  const recall = support > 0 ? tp / support : null;
  const f1 = precision !== null && recall !== null && precision + recall > 0
    ? (2 * precision * recall) / (precision + recall)
    : (support > 0 ? 0 : null);

  per_class[cls] = { precision: r4(precision), recall: r4(recall), f1: r4(f1),
    support, tp, fp, fn };

  if (support > 0) { f1_sum += f1 ?? 0; classes_present += 1; }
}

const macro_f1 = classes_present > 0 ? f1_sum / classes_present : 0;

const confusion = {};
for (const c of cases) {
  const key = `${c.expected}->${c.actual}`;
  confusion[key] = (confusion[key] ?? 0) + 1;
}

const failures = cases.filter((c) => !c.correct);
const false_accepts = failures.filter(
  (c) => c.expected === 'rejected' && c.actual === 'accepted').length;
const false_rejects = failures.filter(
  (c) => c.expected === 'accepted' && c.actual === 'rejected').length;

const prev = $('Previous eval').first().json;
const thresholds = scored[0]?.thresholds ?? {};

return [{ json: {
  ruleset_version: scored[0]?.ruleset_version ?? 'unknown',
  total,
  correct,
  accuracy: r4(accuracy),
  macro_f1: r4(macro_f1),
  per_class,
  confusion,
  false_accepts,
  false_rejects,
  config: { ...thresholds, golden_set_size: total },
  previous_accuracy: prev.previous_accuracy ?? 0,
  delta: r4(accuracy - (prev.previous_accuracy ?? 0)),
  has_history: (prev.history ?? 0) > 0,
  // Capped, because the report is a message and not a database dump. The
  // full list is in eval_cases, which is the point of storing them.
  failures: failures.slice(0, 10),
  cases,
} }];

// One item per case, carrying the run id the insert just returned.
//
// Storing the cases and not only the score is what makes a regression
// actionable. 'Accuracy fell from 0.87 to 0.80' is an alert; 'these four
// rows flipped from review to rejected' is a fix.
const runId = $input.first().json.id;
const cases = $('Compare').first().json.cases;

return cases.map((c) => ({ json: { eval_run_id: runId, ...c } }));

parameters.query:
INSERT INTO eval_cases
  (eval_run_id, external_id, expected, actual, correct, note)
VALUES ($1, $2, $3, $4, $5, $6);

